// Generated by Step 2
package com.example.kyrgyzkeyboard.keyboard

/** 键类型：字母键、符号键、功能键、数字键。 */
enum class KeyType { LETTER, SYMBOL, FUNCTION, DIGITAL }

/** 功能键动作。 */
enum class FunctionType { 
    SPACE, 
    BACKSPACE, 
    NEWLINE, 
    SWITCH_LAYOUT, 
    DONE, 
    SHIFT, 
    SWITCH_LANGUAGE,
    SWITCH_DIGITAL  // 快速切换到数字键盘
}

/**
 * 单个键的数据模型。
 *
 * @param label   键面显示文本
 * @param code    该键提交到编辑器的字符串（功能键为空串）
 * @param type    键类型
 * @param function 若为功能键则表示动作，否则为 null
 * @param variants 该键上的所有字符列表（数字键用） / 同源字母列表（字母键用）
 * @param weight   键宽权重，1f 表示标准键宽
 */
data class KyrgyzKey(
    val label: String,
    val code: String,
    val type: KeyType,
    val function: FunctionType? = null,
    val variants: List<String> = emptyList(),
    val weight: Float = 1f
) {
    companion object {

        /** 创建字母键。 */
        fun letter(char: String, variants: List<String> = emptyList()): KyrgyzKey =
            KyrgyzKey(
                label = char,
                code = char,
                type = KeyType.LETTER,
                variants = variants
            )

        /**
         * 创建数字键盘键（GB/T 31921-2015 标准）。
         * 点击输入数字，长按输入第一个柯尔克孜字母。
         * @param label 键面显示的数字
         * @param symbols 该键上的柯尔克孜字母或符号列表
         */
        fun digitalKey(label: String, symbols: List<String>): KyrgyzKey =
            KyrgyzKey(
                label = label,
                code = label,  // 点击输入数字本身！
                type = KeyType.DIGITAL,
                variants = symbols  // 变体 = 字母列表
            )

        /** 创建符号键。 */
        fun symbol(char: String): KyrgyzKey =
            KyrgyzKey(
                label = char,
                code = char,
                type = KeyType.SYMBOL
            )

        /** 空格键（较宽）。 */
        fun space(label: String = " "): KyrgyzKey =
            KyrgyzKey(
                label = label,
                code = " ",
                type = KeyType.FUNCTION,
                function = FunctionType.SPACE,
                weight = 4f
            )

        /** 退格键。 */
        fun backspace(): KyrgyzKey =
            KyrgyzKey(
                label = "⌫",
                code = "",
                type = KeyType.FUNCTION,
                function = FunctionType.BACKSPACE,
                weight = 1.5f
            )

        /** 换行键。 */
        fun newline(): KyrgyzKey =
            KyrgyzKey(
                label = "⏎",
                code = "\n",
                type = KeyType.FUNCTION,
                function = FunctionType.NEWLINE,
                weight = 1.5f
            )

        /** 切换布局键（字母 <-> 符号）。 */
        fun switchLayout(label: String = "123"): KyrgyzKey =
            KyrgyzKey(
                label = label,
                code = "",
                type = KeyType.FUNCTION,
                function = FunctionType.SWITCH_LAYOUT,
                weight = 1.5f
            )

        /** 快速切换到数字键盘键。 */
        fun switchDigital(label: String = "123"): KyrgyzKey =
            KyrgyzKey(
                label = label,
                code = "",
                type = KeyType.FUNCTION,
                function = FunctionType.SWITCH_DIGITAL,
                weight = 1.2f
            )

        /** 完成 / 收起键盘。 */
        fun done(label: String = "✓"): KyrgyzKey =
            KyrgyzKey(
                label = label,
                code = "",
                type = KeyType.FUNCTION,
                function = FunctionType.DONE,
                weight = 1.5f
            )

        /** Shift 键。 */
        fun shift(): KyrgyzKey =
            KyrgyzKey(
                label = "⇧",
                code = "",
                type = KeyType.FUNCTION,
                function = FunctionType.SHIFT,
                weight = 1.2f
            )

        /** 循环切换输入语言（柯尔克孜 / 英文 / 中文拼音）。 */
        fun switchLanguage(label: String = "🌐"): KyrgyzKey =
            KyrgyzKey(
                label = label,
                code = "",
                type = KeyType.FUNCTION,
                function = FunctionType.SWITCH_LANGUAGE,
                weight = 1.2f
            )
    }
}
